# -*- coding: utf-8 -*-
from ru_base import *

# ---- Спряжение
CONJ = {'читать': ['читаю', 'читаешь', 'читает', 'читаем', 'читаете', 'читают'], 'думать': ['думаю', 'думаешь', 'думает', 'думаем', 'думаете', 'думают'], 'играть': ['играю', 'играешь', 'играет', 'играем', 'играете', 'играют'],
        'писать': ['пишу', 'пишешь', 'пишет', 'пишем', 'пишете', 'пишут'], 'жить': ['живу', 'живёшь', 'живёт', 'живём', 'живёте', 'живут'], 'пить': ['пью', 'пьёшь', 'пьёт', 'пьём', 'пьёте', 'пьют'],
        'говорить': ['говорю', 'говоришь', 'говорит', 'говорим', 'говорите', 'говорят'], 'учить': ['учу', 'учишь', 'учит', 'учим', 'учите', 'учат'], 'любить': ['люблю', 'любишь', 'любит', 'любим', 'любите', 'любят'],
        'смотреть': ['смотрю', 'смотришь', 'смотрит', 'смотрим', 'смотрите', 'смотрят'], 'ходить': ['хожу', 'ходишь', 'ходит', 'ходим', 'ходите', 'ходят']}
PRON = ['я', 'ты', 'он', 'мы', 'вы', 'они']
def cj1():
    v = ch(list(CONJ)); i = R.randrange(6); return mc(f'Выберите правильную форму: {PRON[i]} ___ ({v}).', CONJ[v][i], wr(CONJ[v], CONJ[v][i]))
def cj2():
    v = ch(list(CONJ)); i = R.randrange(6); return mc(f'Какая форма глагола «{v}» подходит к местоимению «{PRON[i]}»?', CONJ[v][i], wr(CONJ[v], CONJ[v][i]))
C1 = ['читать', 'думать', 'играть', 'знать', 'работать', 'гулять', 'рисовать', 'писать', 'жить', 'пить', 'ехать', 'идти', 'петь', 'мыть']
C2 = ['говорить', 'смотреть', 'учить', 'любить', 'ходить', 'спать', 'стоять', 'видеть', 'слышать', 'дышать', 'держать', 'лететь']
def cj3():
    if R.random() < .5:
        v = ch(C1 + C2); r = 'I спряжение' if v in C1 else 'II спряжение'; return mc(f'К какому спряжению относится глагол «{v}»?', r, wr(['I спряжение', 'II спряжение', 'разноспрягаемый глагол', 'не спрягается'], r))
    return ch([mc('Какие окончания имеет I спряжение (3-е лицо мн. ч.)?', '-ут / -ют', ['-ат / -ят', '-ит / -ет', '-ешь / -ишь']), mc('Какие окончания имеет II спряжение (3-е лицо мн. ч.)?', '-ат / -ят', ['-ут / -ют', '-ем / -им', '-ешь / -ет']),
               mc('Окончание 2-го лица ед. ч. у глаголов I спряжения:', '-ешь', ['-ишь', '-ет', '-ит']), mc('Окончание 2-го лица ед. ч. у глаголов II спряжения:', '-ишь', ['-ешь', '-ет', '-ут'])])
B.topic(BM, 'r_spryag', 'Спряжение глагола — Fe’l tuslanishi', [7, 8], cj1, cj2, cj3, 'спряжение глагола fe’l tuslanish')

# ---- Наклонение, повелительное
cls(BM, 'r_naklon', 'Наклонение глагола — Fe’l mayli', [7, 8], {
    'изъявительное наклонение': ['Я читаю книгу.', 'Вчера мы ходили в парк.', 'Завтра будет дождь.', 'Брат решает задачу.', 'Мама приготовила обед.'],
    'повелительное наклонение': ['Прочитай рассказ!', 'Закройте окно.', 'Иди домой!', 'Помоги маме.', 'Откройте тетради.'],
    'условное наклонение': ['Если бы я знал, я бы пришёл.', 'Я бы пошёл гулять.', 'Мама купила бы торт.', 'Мы бы поехали к морю.', 'Он бы помог тебе.']},
    lambda x: f'В каком наклонении глагол в предложении: «{x}»', lambda c: f'В каком предложении глагол стоит в форме: {c}?', lambda c: f'В каком предложении глагол НЕ стоит в форме: {c}?', 'наклонение глагола fe’l mayli', decoys=['неопределённая форма (инфинитив)'])

IMP = {'читать': 'читай', 'писать': 'пиши', 'говорить': 'говори', 'смотреть': 'смотри', 'идти': 'иди', 'встать': 'встань', 'принести': 'принеси', 'открыть': 'открой', 'закрыть': 'закрой',
       'слушать': 'слушай', 'помогать': 'помогай', 'делать': 'делай', 'дать': 'дай', 'купить': 'купи'}
def im1():
    v = ch(list(IMP)); return mc(f'Повелительная форма глагола «{v}» (ты):', IMP[v], wr(list(IMP.values()), IMP[v]))
def im2():
    v = ch(list(IMP)); f = IMP[v]; return mc(f'От какого глагола образована форма «{f}»?', v, wr(list(IMP), v))
def im3():
    v = ch(list(IMP)); f = IMP[v]; return mc(f'Как сказать вежливо нескольким людям (вы)? «{f}» →', f + 'те', [f + 'ть', f + 'ся', f[:-1] + 'ете'])
B.topic(BM, 'r_povel', 'Повелительное наклонение', [7, 8], im1, im2, im3, 'повелительное наклонение buyruq')

# ---- Переходность
TR = {'переходный глагол': ['читать (книгу)', 'писать (письмо)', 'видеть (птицу)', 'строить (дом)', 'любить (маму)', 'слушать (музыку)', 'купить (хлеб)', 'решать (задачу)'],
      'непереходный глагол': ['идти', 'спать', 'расти', 'сидеть', 'лежать', 'стоять', 'жить', 'плакать', 'смеяться', 'улыбаться', 'умываться', 'учиться']}
cls(BM, 'r_perehod', 'Переходные и непереходные глаголы — O’timli va o’timsiz fe’llar', [7, 8], TR, lambda x: f'Какой это глагол: «{x}»?', lambda c: f'Какой из этих глаголов — {c}?', lambda c: f'Какой глагол НЕ входит в группу «{c}»?', 'переходные непереходные глаголы oʻtimli')

# ---- Глаголы движения
MV = [('Каждый день я ___ в школу пешком.', 'хожу', ['иду', 'ходит', 'идёт']), ('Вчера мы ___ в парк и вернулись.', 'ходили', ['шли', 'идут', 'иду']), ('Самолёт ___ в Москву (сейчас).', 'летит', ['летает', 'летают', 'лечу']),
      ('Птицы умеют ___.', 'летать', ['лететь', 'летит', 'летят']), ('Рыбы ___ в воде.', 'плавают', ['плывёт', 'плыву', 'плывёшь']), ('Я каждый год ___ к бабушке на автобусе.', 'езжу', ['еду', 'иду', 'хожу']),
      ('Смотри! Мальчик ___ к нам прямо сейчас.', 'бежит', ['бегает', 'бегают', 'бежите']), ('Дети любят ___ по утрам.', 'бегать', ['бежать', 'бежит', 'бегут']), ('Он ___ портфель в руках (сейчас).', 'несёт', ['носит', 'носят', 'несу'])]
MF = {'идти': ['иду', 'идёшь', 'идёт', 'идём', 'идёте', 'идут'], 'ходить': ['хожу', 'ходишь', 'ходит', 'ходим', 'ходите', 'ходят'], 'ехать': ['еду', 'едешь', 'едет', 'едем', 'едете', 'едут'],
      'ездить': ['езжу', 'ездишь', 'ездит', 'ездим', 'ездите', 'ездят'], 'лететь': ['лечу', 'летишь', 'летит', 'летим', 'летите', 'летят'], 'летать': ['летаю', 'летаешь', 'летает', 'летаем', 'летаете', 'летают'],
      'бежать': ['бегу', 'бежишь', 'бежит', 'бежим', 'бежите', 'бегут'], 'бегать': ['бегаю', 'бегаешь', 'бегает', 'бегаем', 'бегаете', 'бегают'], 'плыть': ['плыву', 'плывёшь', 'плывёт', 'плывём', 'плывёте', 'плывут'],
      'плавать': ['плаваю', 'плаваешь', 'плавает', 'плаваем', 'плаваете', 'плавают']}
MP = [('идти', 'ходить', 'в школу пешком'), ('ехать', 'ездить', 'в город на автобусе'), ('лететь', 'летать', 'в Москву на самолёте'), ('бежать', 'бегать', 'по парку'), ('плыть', 'плавать', 'по реке на лодке')]
def mv():
    q, r, w = ch(MV); return mc(q, r, w)
def mg():
    a, b, place = ch(MP); i = R.randrange(6)
    if R.random() < .5: return mc(f'Сейчас {PRON[i]} ___ {place}. (одно направление, один раз)', MF[a][i], [MF[b][i]] + R.sample([x for j, x in enumerate(MF[a]) if j != i], 2))
    return mc(f'Каждый день {PRON[i]} ___ {place}. (много раз, регулярно)', MF[b][i], [MF[a][i]] + R.sample([x for j, x in enumerate(MF[b]) if j != i], 2))
def mq():
    a, b, place = ch(MP)
    return ch([mc(f'Какой глагол обозначает регулярное, повторяющееся движение?', b, [a, 'стоять', 'сидеть']), mc(f'Какой глагол обозначает движение в одном направлении в данный момент?', a, [b, 'стоять', 'лежать']),
               mc(f'Как будет «yurmoq (piyoda)» ruscha?', 'идти / ходить', ['ехать / ездить', 'лететь / летать', 'плыть / плавать']), mc('Как будет «uchmoq» ruscha?', 'лететь / летать', ['бежать / бегать', 'идти / ходить', 'плыть / плавать']),
               mc('Как будет «suzmoq» ruscha?', 'плыть / плавать', ['бежать / бегать', 'лететь / летать', 'ехать / ездить']), mc('Как будет «yugurmoq» ruscha?', 'бежать / бегать', ['плыть / плавать', 'лететь / летать', 'идти / ходить']),
               mc('Как будет «(transportda) bormoq» ruscha?', 'ехать / ездить', ['идти / ходить', 'бежать / бегать', 'плыть / плавать'])])
B.topic(BM, 'r_dvij', 'Глаголы движения — Harakat fe’llari', [6, 7, 8], lambda: ch([mg, mq])(), mg, lambda: ch([mg, mv])(), 'глаголы движения идти ходить ехать')
